SELECT COUNT(*) FROM badges as b, comments as c, postLinks as pl, postHistory as ph, votes as v, users as u, posts as p WHERE c.UserId = u.Id AND p.Id = c.PostId AND p.Id = ph.PostId AND b.UserId = u.Id AND p.Id = pl.RelatedPostId AND p.Id = v.PostId AND b.Date>='2010-07-30 03:49:24'::timestamp AND c.CreationDate>='2010-07-26 20:21:15'::timestamp AND c.CreationDate<='2014-09-13 18:12:10'::timestamp AND v.VoteTypeId=2 AND v.CreationDate>='2010-07-27 00:00:00'::timestamp;